    if(!moov) throw new Error('MOV moov missing');
    const bytes=Buffer.alloc(moov.size);if(fs.readSync(fd,bytes,0,bytes.length,moov.at)!==bytes.length) throw new Error('MOV moov truncated');
    const state={colors:0};const tagged=rewrite(bytes,state);if(state.colors!==1) throw new Error('MOV color count');
    let written=0;while(written<tagged.length){const n=fs.writeSync(fd,tagged,written,tagged.length-written,moov.at+written);if(!n)throw new Error('MOV color write');written+=n;}
    fs.ftruncateSync(fd,moov.at+tagged.length);
